import pytest

from client import Transient, call


def test_retries_until_success():
    state = {'n': 0}

    def flaky():
        state['n'] += 1
        if state['n'] < 3:
            raise Transient('nope')
        return 'ok'

    assert call(flaky, attempts=3) == 'ok'
    assert state['n'] == 3


def test_gives_up():
    def always():
        raise Transient('nope')

    with pytest.raises(Transient):
        call(always, attempts=2)


def test_non_transient_not_retried():
    state = {'n': 0}

    def boom():
        state['n'] += 1
        raise ValueError('fatal')

    with pytest.raises(ValueError):
        call(boom, attempts=3)
    assert state['n'] == 1

from backoff import delays


class Transient(Exception):
    pass


def call(fn, attempts=3):
